// ==== KIKE · variantes de la máscara según el gesto ====
//   Cejas arriba  -> estrellas amarillas
//   Boca abierta  -> KIKE negro
//   Sonrisa       -> patrón andino (chakana)
//   (al aparecer la cara vuelve el KIKE rojo base)
// this -> mesh_0 (la máscara). Los PNG viven en assets/filtro/ (UV canónica de MediaPipe).

const ARCHIVOS = ['v0-rojo', 'v1-estrellas', 'v2-negro', 'v3-andino'];
const texturas = [];
let actual = 0;
let ultimo = 0;

function avisar(i) {
	if (window.kikeFiltro && window.kikeFiltro.onVariant) window.kikeFiltro.onVariant(i);
}

function poner(i, forzar) {
	const ahora = performance.now();
	if (!texturas[i]) return;
	if (!forzar && (i === actual || ahora - ultimo < 550)) return;
	this.material.map = texturas[i];
	this.material.needsUpdate = true;
	actual = i;
	ultimo = ahora;
	avisar(i);
}

function init() {
	const loader = new THREE.TextureLoader();
	ARCHIVOS.forEach((nombre, i) => {
		loader.load('./assets/filtro/' + nombre + '.png', (t) => {
			t.colorSpace = THREE.SRGBColorSpace;
			t.anisotropy = 4;
			texturas[i] = t;
			if (i === 0) { this.material.map = t; this.material.needsUpdate = true; }
		});
	});
	// Para tocar los chips de la interfaz
	const mascara = this;
	window.kikeSetVariant = (i) => poner.call(mascara, i, true);
}

function faceFound() {
	poner.call(this, 0, true);
	if (window.kikeFiltro && window.kikeFiltro.onFound) window.kikeFiltro.onFound();
}

function browRaise() { poner.call(this, 1); }
function mouthOpen() { poner.call(this, 2); }
function smileStart() { poner.call(this, 3); }
